INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (9999,'JajaFinance_CreditCard','$source = \"Jaja Finance UK\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD NO_OPENING_BALANCE SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// Delete page 2 (Useful Information) and page 4 (blank)\ndelete all pages containing \"Useful Information\"\ndelete all pages containing \"Jaja Finance Ltd is authorised\"\n\ngo to page 1\n\n// Get account name and number\n$accountName = get line starting \"MISS\" => get text\n$accountNumber = get line containing \"Account number:\" => take last words 1 => get text\n\n// Get period to (statement date)\n$periodTo = get line containing \"Statement date:\" => take last words 3 => get date \"d MMM yyyy\"\n\n// Get period from (use due date line as anchor for the earliest transaction month - derive from transactions)\n// Period from: use the opening balance date context - not explicitly shown, so use periodTo minus 1 month approximation\n// Actually extract from transaction dates - first transaction is 28 Apr so periodFrom approximated\n// Use the \"Payment due from previous statement\" section - not a date. Use statement date as periodTo only.\n// $periodFrom not available explicitly; set to same as periodTo as fallback - script will rely on transactions\n$periodFrom = get line containing \"Statement date:\" => take last words 3 => get date \"d MMM yyyy\"\n\n// Opening balance = Statement balance last month\n$openingBalance = get line starting \"Statement balance last month\" => take last words 1 => get decimal\n\n// Closing balance = Outstanding statement balance\n$closingBalance = get line starting \"Outstanding statement balance\" => take last words 1 => get decimal\n\n// Delete left-hand sidebar text on page 1 to avoid interference\n@sidebarBottom = get line starting \"Your Transactions\" => top\ndelete text in box page.top @sidebarBottom page.left page.middleX\n\n// Delete the \"Continued on the next page\" footer line\ndelete all lines containing \"Continued on the next page\"\ndelete all lines containing \"Continued on the next\"\n\n// Delete the header row that repeats on page 3\ndelete all lines starting \"Previous Balance\"\ndelete all lines containing \"Transaction Posting\"\ndelete all lines starting \"Your Transactions\"\ndelete all lines starting \"MISS CHANELLE\"\n\n// Get start of table - line below the column header\ngo to page 1\n@transactionsTop = get line containing \"Date Date Description Amount\" => bottom => get line below\n\n// Get end of table\ngo to last page\n@transactionsBottom = get line starting \"Total for new transactions\" => top => get line above\n\n// Discard page header repetition\nget last line containing \"Date Date Description Amount\" => bottom => ignore header above\n\n// Discard footer\ngo to page 1\nget line above 0 => top => ignore footer below\n\n// Read transactions table: Transaction Date | Posting Date | Description | Amount\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 60 110 450 page.right => describe table false \"*Date[dd MMM]\" - Details *#Credit',UTC_TIMESTAMP(),0);
INSERT INTO `digitalpdf$documentidentification` (`Id`,`Name`,`TitlePattern`,`AuthorPattern`,`CreatorPattern`,`ProducerPattern`,`Version`,`PageCount`,`SignatureInfo`,`ContainsText`,`ExcludesText`,`ScriptId`,`VerificationRuleSetId`,`ModificationTimeUtc`,`IsDeleted`) VALUES (9990,'JajaFinance_CreditCard',NULL,NULL,'.*','.*',NULL,NULL,NULL,'[\"Your credit card statement\",\"jaja.co.uk\",\"Outstanding statement balance\",\"Transaction Posting\"]',NULL,9999,4,UTC_TIMESTAMP(),0);